/**
 * Preference Extension
 *
 * Purpose: resolves user preferences from explicit controls, persisted values
 * and system media queries, then reflects selected values on the document.
 *
 * Capability profile: interaction and input, structure and state, visual
 * preference policy, and integration with storage and `matchMedia`.
 *
 * Inputs and activation: mounts `[data-ae-preference]`; option, next and previous
 * controls use their matching data attributes. Init options define values,
 * defaults and storage behavior. Bootstrap color-mode synchronization belongs
 * to the boot's preference publisher, not this Extension.
 *
 * Outputs and owned state: updates preference attributes on the root HTML
 * element, synchronizes options, value labels and associated inputs, persists
 * eligible values and dispatches `AelluxJsPreferencesChange`.
 *
 * Lifecycle: removes container handlers, storage and media-query listeners, and
 * releases its internal registries when destroyed.
 *
 * Accessibility: control markup must provide native keyboard behavior,
 * accessible names and semantic state. The extension synchronizes values and
 * checked state and option buttons' pressed state, but does not turn a generic
 * element into an accessible control.
 */

import utilsNameCase from "./internal/utils-name-case.js";

(function (root) {
  "use strict";

  const AelluxJs = root.AelluxJs;
  const { toCamelCase } = utilsNameCase;

  const extensionName = "preference";
  if (!AelluxJs) {
    throw new Error(`[aellux.js] Cannot attach the "${extensionName}" extension: root.AelluxJs is not defined. Load the aellux.js boot script before this extension.`);
  }

  const NO_PREFERENCE = "no-preference";

  const userPreferences = Object.create(null);
  const defaultPreferences = Object.create(null);
  const computedPreferences = Object.create(null);
  const containersByPreference = new Map();
  const containerPreferences = new Map();
  const containerLabels = new Map();
  const labelMemories = new WeakMap();
  const containerOptionAria = new Map();

  AelluxJs.extAttach(extensionName, { init, destroy, update, get, set });

  const attr = {
    preference: AelluxJs.attr("preference"),
    option: AelluxJs.attr("option"),
    label: AelluxJs.attr("label"),
    next: AelluxJs.attr("next"),
    prev: AelluxJs.attr("prev"),
    ready: AelluxJs.attr("ready"),
  }

  const className = {
    active: AelluxJs.className("active")
  }

  const prefOptions = {
    colorScheme: ["auto", "light", "dark"],
    contrast: ["auto", NO_PREFERENCE, "more", "less"],
    reducedMotion: ["auto", NO_PREFERENCE, "reduced"],
    reducedTransparency: ["auto", NO_PREFERENCE, "reduced"],
    forcedColors: ["auto", NO_PREFERENCE, "active"],
    textScale: [1, 1.5, 0.8],
    interfaceScale: [1, 1.5, 0.8],
    extendedTiming: ["off", "on"],
    largeTargets: ["off", "on"],
    haptics: ["on", "off"],
    sound: ["off", "on", "low"],
  };

  function init(options) {
    AelluxJs.mountManager.add({
      extensionName, selector: `[${attr.preference}]`,
      priority: 0,
      mount: mountPreferenceContainer, unmount: unmountPreferenceContainer
    });

    AelluxJs.onEvent(window, "$storage", storageEvent);

    //Watch device changes
    const allQueries = AelluxJs.registry.preferenceMediaQueries;
    Object.values(allQueries).forEach((queries) =>
      Object.values(queries).forEach((query) => {
        if (!query) return;
        if (query.addEventListener) {
          AelluxJs.onEvent(query, "$change", update);
        } else if (query.addListener) {
          query.addListener(update);
        }
      }
      )
    );

    //Default values
    Object.entries(prefOptions)
      .forEach(([param, options]) => {
        defaultPreferences[param] = options[0];
      });

    loadUserPreferences();
    update();
  }

  function destroy() {
    for (const container of containerPreferences.keys()) unmountPreferenceContainer(container);
    AelluxJs.mountManager.remove({ extensionName });
    containersByPreference.clear();
    containerPreferences.clear();
    AelluxJs.offEvent(window, "$storage", storageEvent);
    AelluxJs.off('$DOMContentLoaded', update);

    const allQueries = AelluxJs.registry.preferenceMediaQueries;
    Object.values(allQueries).forEach((queries) =>
      Object.values(queries).forEach((query) => {
        if (!query) return;
        if (query.removeEventListener) {
          AelluxJs.offEvent(query, "$change", update);
        } else if (query.removeListener) {
          query.removeListener(update);
        }
      }
      )
    );
  }

  function get(preference) {
    const key = toCamelCase(preference);
    return computedPreferences[key];
  }

  function set(preference, value) {
    const key = toCamelCase(preference);
    if (userPreferences[key] === value) return;
    userPreferences[key] = value;
    saveUserPreferences();
  }

  function storageEvent(event) {
    if (event.key !== "AelluxJsPreferences") return;
    const newPreferences = new URLSearchParams(event.newValue || "");
    Object.keys(userPreferences).forEach(key => delete userPreferences[key]);
    newPreferences.forEach((value, key) => {
      userPreferences[key] = value;
    });
    update();
  }

  function update() {
    const nextPreferences = Object.assign(Object.create(null), defaultPreferences, userPreferences);
    const changed = new Set();
    for (const key in computedPreferences) {
      if (!(key in nextPreferences)) {
        delete computedPreferences[key];
        changed.add(key);
      }
    }
    for (const key in nextPreferences) {
      if (computedPreferences[key] !== nextPreferences[key]) changed.add(key);
      computedPreferences[key] = nextPreferences[key];
    }
    AelluxJs.updatePreferenceAttributesHTML(computedPreferences);
    for (const container of containerPreferences.keys()) {
      if (indexContainer(container)) updateContainer(container);
    }
    for (const key of changed) {
      const containers = containersByPreference.get(key);
      if (containers) for (const container of containers) updateContainer(container);
    }
    AelluxJs.dispatch("PreferencesChange", {
      detail: {
        changed: Array.from(changed),
        preferences: Object.assign({}, computedPreferences)
      }
    });
  }

  function indexContainer(container) {
    const key = toCamelCase(container.getAttribute(attr.preference) || "");
    const previous = containerPreferences.get(container);
    if (previous === key) return false;
    if (previous !== undefined) {
      const containers = containersByPreference.get(previous);
      containers.delete(container);
      if (!containers.size) containersByPreference.delete(previous);
    }
    let containers = containersByPreference.get(key);
    if (!containers) {
      containers = new Set();
      containersByPreference.set(key, containers);
    }
    containers.add(container);
    containerPreferences.set(container, key);
    return true;
  }

  function isOptionButton(element) {
    const role = element.getAttribute("role");
    if (role) return role === "button";
    return element.tagName === "BUTTON" ||
      (element.tagName === "INPUT" && /^(button|submit|reset)$/.test(element.type));
  }

  function updateContainer(container) {
    const preference = container.getAttribute(attr.preference);
    const elements = container.querySelectorAll(`[${attr.option}]`);
    const labels = container.querySelectorAll(`[${attr.label}]`);
    const currentValue = get(preference || "");
    let optionAria = containerOptionAria.get(container);
    if (!optionAria) containerOptionAria.set(container, optionAria = new Map());
    for (const [element, handler] of optionAria) {
      if (!container.contains(element) || !element.hasAttribute(attr.option) || !isOptionButton(element)) {
        handler.release();
        optionAria.delete(element);
      }
    }
    labels.forEach(label => {
      let ownedLabels = containerLabels.get(container);
      if (!ownedLabels) {
        ownedLabels = new Set();
        containerLabels.set(container, ownedLabels);
      }
      if (!ownedLabels.has(label)) {
        labelMemories.set(label, AelluxJs.persist.element.save(label, ["hidden"], []));
        ownedLabels.add(label);
      }
      const value = label.getAttribute(attr.label);
      const selected = String(value) === String(currentValue);
      label.hidden = !selected;
    });
    elements.forEach(element => {
      const value = element.getAttribute(attr.option);
      const selected = String(value) === String(currentValue);
      element.classList.toggle(className.active, selected);
      if (isOptionButton(element)) {
        if (!optionAria.has(element)) optionAria.set(element, AelluxJs.aria.register(element));
        optionAria.get(element).set({ pressed: selected });
      }
      const labelFor = element.getAttribute("for");
      if (labelFor) {
        const forTarget = document.getElementById(labelFor);
        if (forTarget) {
          if ("value" in forTarget) forTarget.value = value;
          if ("checked" in forTarget) forTarget.checked = selected;
        }
      }
    });
  }

  function saveUserPreferences() {
    AelluxJs.persist.preferences.setObject(userPreferences);
  }

  function loadUserPreferences() {
    Object.assign(userPreferences, AelluxJs.persist.preferences.getObject());
  }

  function mountPreferenceContainer(container) {
    indexContainer(container);
    updateContainer(container);
    AelluxJs.onEvent(container, "$click", onContainerClick);
  }

  function unmountPreferenceContainer(container) {
    AelluxJs.offEvent(container, "$click", onContainerClick);
    const optionAria = containerOptionAria.get(container);
    if (optionAria) for (const handler of optionAria.values()) handler.release();
    containerOptionAria.delete(container);
    const labels = containerLabels.get(container);
    if (labels) for (const label of labels) {
      labelMemories.get(label)?.restore();
      labelMemories.delete(label);
    }
    containerLabels.delete(container);
    const key = containerPreferences.get(container);
    if (key === undefined) return;
    const containers = containersByPreference.get(key);
    containers.delete(container);
    if (!containers.size) containersByPreference.delete(key);
    containerPreferences.delete(container);
  }

  function onContainerClick(event) {
    const container = event.currentTarget;
    if (!event.target) return;
    const optionButton = event.target.closest(`[${attr.option}]`);
    const buttonNext = event.target.closest(`[${attr.next}]`);
    const buttonPrev = event.target.closest(`[${attr.prev}]`);
    if (optionButton) {
      const preference = container.getAttribute(attr.preference);
      const value = optionButton.getAttribute(attr.option);
      set(preference, value);
      update();
    } else if (buttonNext || buttonPrev) {
      const preference = container.getAttribute(attr.preference);
      const key = toCamelCase(preference);
      const options = prefOptions[key];
      if (!options || options.length === 0) return;

      const change = buttonNext ? 1 : -1;
      const currentValue = get(key);
      const currentIndex = options.findIndex(option =>
        String(option) === String(currentValue)
      );
      const nextIndex = currentIndex < 0
        ? (buttonNext ? 0 : options.length - 1)
        : (currentIndex + change + options.length) % options.length;

      set(preference, options[nextIndex]);
      update();
    }
  }

})(typeof globalThis !== "undefined" ? globalThis : window);
